import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"MythicMobs Integration","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/mythic.md","filePath":"en/modules/attribute/mythic.md","lastUpdated":0}`),a={name:`en/modules/attribute/mythic.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="mythicmobs-integration" tabindex="-1">MythicMobs Integration <a class="header-anchor" href="#mythicmobs-integration" aria-label="Permalink to “MythicMobs Integration”">​</a></h1><p>EmakiAttribute integrates with MythicMobs for attribute damage mechanics, attribute conditions, and mob attribute configuration.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>MythicMobs is a soft dependency. If it is not installed, related features are skipped.</p></div><h2 id="skill-mechanic-emaki-damage" tabindex="-1">Skill mechanic: <code>emaki_damage</code> <a class="header-anchor" href="#skill-mechanic-emaki-damage" aria-label="Permalink to “Skill mechanic: emaki_damage”">​</a></h2><p>Aliases: <code>emakiattribute_damage</code>, <code>attribute_damage</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>damage</code></td><td>double</td><td>skill power</td><td>Base damage.</td></tr><tr><td><code>damage_type</code></td><td>string</td><td>—</td><td>Damage type id, such as <code>physical</code> or <code>spell</code>.</td></tr><tr><td><code>allow_critical</code></td><td>boolean</td><td><code>true</code></td><td>Whether critical hits are allowed.</td></tr><tr><td><code>allow_target_dodge</code></td><td>boolean</td><td><code>false</code></td><td>Whether target dodge is allowed.</td></tr><tr><td><code>calculate_target_defense</code></td><td>boolean</td><td><code>true</code></td><td>Whether target defense is calculated.</td></tr><tr><td><code>trigger_mythic_on_damaged</code></td><td>boolean</td><td><code>false</code></td><td>Whether MythicMobs on-damaged behavior is triggered.</td></tr></tbody></table><p>Example:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">FireBlast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  Skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_damage{damage=50;damage_type=spell;allow_critical=true} @target</span></span></code></pre></div><h2 id="skill-mechanics-temporary-attributes" tabindex="-1">Skill mechanics: temporary attributes <a class="header-anchor" href="#skill-mechanics-temporary-attributes" aria-label="Permalink to “Skill mechanics: temporary attributes”">​</a></h2><p>These mechanics target skill targets (<code>@target</code>, <code>@self</code>, etc.) and work on both <strong>players and mobs</strong>. Temporary attributes are removed automatically on expiry and are not persisted (they are lost on restart).</p><div class="warning custom-block"><p class="custom-block-title">Upgrade notes: timed attribute behaviour changes</p><ol><li><strong><code>emaki_attribute_add_tag</code> no longer produces composite effect IDs.</strong> <code>effect_prefix=poison</code> used to write one separate <code>poison:&lt;attributeId&gt;</code> record per matched attribute; they now all join a single <code>poison</code> <strong>effect group</strong>. Configuration deleting a composite ID no longer matches — use <code>emaki_attribute_remove{effect_id=poison}</code> instead, which previously removed nothing and now works.</li><li><strong>Multi-group SET (<code>set=true</code>) on the same attribute now has a defined winner</strong>: the last write, no longer dependent on internal hash-map iteration order.</li></ol><p>Single-attribute skill configuration is unaffected. Also note that low-level refusals (unregistered attribute, invalid <code>stack_mode</code>, <code>NaN</code>) used to still return <code>SUCCESS</code>; they now return <code>INVALID_CONFIG</code> and log a console warning.</p></div><h3 id="emaki-attribute-add" tabindex="-1"><code>emaki_attribute_add</code> <a class="header-anchor" href="#emaki-attribute-add" aria-label="Permalink to “emaki_attribute_add”">​</a></h3><p>Alias: <code>emakiattribute_add</code>. Adds one temporary attribute to the target.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>string</td><td>—</td><td><strong>Effect group id.</strong> Several attributes can share one id: they coexist and <code>emaki_attribute_remove</code> clears the whole group. The stack mode only applies when the same attribute is re-applied inside the same group. Aliases: <code>effectid</code>, <code>id</code>.</td></tr><tr><td><code>attribute</code></td><td>string</td><td>—</td><td>Attribute id. An unregistered id returns <code>INVALID_CONFIG</code> and logs a warning. Aliases: <code>attribute_id</code>, <code>attributeid</code>.</td></tr><tr><td><code>value</code></td><td>double</td><td><code>0</code></td><td>Temporary value. <code>NaN</code> / <code>±Inf</code> return <code>INVALID_CONFIG</code>. Aliases: <code>amount</code>, <code>v</code>.</td></tr><tr><td><code>duration</code></td><td>int</td><td>—</td><td>Duration in ticks, must be greater than 0. Aliases: <code>duration_ticks</code>, <code>ticks</code>, <code>d</code>.</td></tr><tr><td><code>stack_mode</code></td><td>string</td><td>attribute default</td><td><code>REPLACE</code> or <code>STACK</code>. Falls back to the attribute&#39;s <code>temporary_stack_mode</code>; any other value returns <code>INVALID_CONFIG</code> instead of silently falling back. Aliases: <code>stackmode</code>, <code>mode</code>.</td></tr><tr><td><code>set</code></td><td>boolean</td><td><code>false</code></td><td>When <code>true</code>, uses overwrite (SET) instead of additive (ADD). Alias: <code>override_value</code>.</td></tr></tbody></table><p>A target that is not a <code>LivingEntity</code> returns <code>INVALID_TARGET</code>.</p><h3 id="emaki-attribute-remove" tabindex="-1"><code>emaki_attribute_remove</code> <a class="header-anchor" href="#emaki-attribute-remove" aria-label="Permalink to “emaki_attribute_remove”">​</a></h3><p>Alias: <code>emakiattribute_remove</code>. Clears every temporary attribute inside the <code>effect_id</code> group.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>string</td><td>Effect group id to clear; every attribute in that group is removed. Returns <code>CONDITION_FAILED</code> when the target carries no such group, and <code>INVALID_TARGET</code> when the target is not a <code>LivingEntity</code>. Aliases: <code>effectid</code>, <code>id</code>.</td></tr></tbody></table><h3 id="emaki-attribute-add-tag" tabindex="-1"><code>emaki_attribute_add_tag</code> <a class="header-anchor" href="#emaki-attribute-add-tag" aria-label="Permalink to “emaki_attribute_add_tag”">​</a></h3><p>Alias: <code>emakiattribute_add_tag</code>. Adds a temporary attribute for every attribute whose <code>tags</code> contain the given tag, placing them <strong>all into one effect group</strong>, so <code>emaki_attribute_remove</code> with that group id clears the whole set at once.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tag</code></td><td>string</td><td>—</td><td>Attribute tag (e.g. <code>DEBUFF</code>), case-insensitive. Aliases: <code>tags</code>, <code>t</code>.</td></tr><tr><td><code>value</code></td><td>double</td><td><code>0</code></td><td>Value applied to every matching attribute. Aliases: <code>amount</code>, <code>v</code>.</td></tr><tr><td><code>duration</code></td><td>int</td><td>—</td><td>Duration in ticks, must be greater than 0. Aliases: <code>duration_ticks</code>, <code>ticks</code>, <code>d</code>.</td></tr><tr><td><code>effect_prefix</code></td><td>string</td><td><code>tag:&lt;tag&gt;</code></td><td>Effect group id that every matched attribute joins. Aliases: <code>effectprefix</code>, <code>prefix</code>.</td></tr><tr><td><code>stack_mode</code></td><td>string</td><td>per-attribute default</td><td><code>REPLACE</code> or <code>STACK</code>. Falls back to each attribute&#39;s <code>temporary_stack_mode</code>; any other value returns <code>INVALID_CONFIG</code>. Aliases: <code>stackmode</code>, <code>mode</code>.</td></tr></tbody></table><p>A target that is not a <code>LivingEntity</code> returns <code>INVALID_TARGET</code>.</p><h3 id="emaki-attribute-clear-tag" tabindex="-1"><code>emaki_attribute_clear_tag</code> <a class="header-anchor" href="#emaki-attribute-clear-tag" aria-label="Permalink to “emaki_attribute_clear_tag”">​</a></h3><p>Alias: <code>emakiattribute_clear_tag</code>. Clears every temporary attribute whose attribute carries the given tag.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>tag</code></td><td>string</td><td>Attribute tag, case-insensitive. Aliases: <code>tags</code>, <code>t</code>. A target that is not a <code>LivingEntity</code> returns <code>INVALID_TARGET</code>.</td></tr></tbody></table><p>Example:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">CurseStrike</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  Skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute_add{effect_id=curse_slow;attribute=movement_speed;value=-2;duration=100} @target</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute_add_tag{tag=DEBUFF;value=-10;duration=100;stack_mode=STACK} @target</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Purify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  Skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute_clear_tag{tag=DEBUFF} @target</span></span></code></pre></div><h2 id="condition-emaki-attribute" tabindex="-1">Condition: <code>emaki_attribute</code> <a class="header-anchor" href="#condition-emaki-attribute" aria-label="Permalink to “Condition: emaki_attribute”">​</a></h2><p>Aliases: <code>emakiattribute_attribute</code>, <code>attribute_value</code>, <code>attribute_resource</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>attribute</code></td><td>Attribute id when checking an attribute value.</td></tr><tr><td><code>resource</code></td><td>Resource id when checking a resource value. Players only.</td></tr><tr><td><code>field</code></td><td>Resource field: <code>current</code> (aliases <code>current_value</code>, <code>value</code>), <code>max</code> (alias <code>current_max</code>), <code>default</code> (alias <code>default_max</code>), <code>bonus</code> (alias <code>bonus_max</code>), or <code>percent</code>. Defaults to <code>current</code>.</td></tr><tr><td><code>operator</code></td><td>Comparison operator.</td></tr><tr><td><code>value</code></td><td>Comparison value.</td></tr><tr><td><code>value_2</code></td><td>Second value for <code>between</code>.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Operator</th><th>Aliases</th><th>Description</th></tr></thead><tbody><tr><td><code>&gt;</code></td><td><code>gt</code></td><td>Greater than.</td></tr><tr><td><code>&gt;=</code></td><td><code>gte</code></td><td>Greater than or equal (default).</td></tr><tr><td><code>&lt;</code></td><td><code>lt</code></td><td>Less than.</td></tr><tr><td><code>&lt;=</code></td><td><code>lte</code></td><td>Less than or equal.</td></tr><tr><td><code>!=</code></td><td><code>&lt;&gt;</code>, <code>ne</code></td><td>Not equal.</td></tr><tr><td><code>between</code></td><td>—</td><td>Between <code>value</code> and <code>value_2</code>, inclusive and order-independent.</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Omitting <code>operator</code> or supplying an unrecognized one falls back to <code>&gt;=</code>. There is no dedicated equality operator.</p></div><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Conditions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki_attribute{resource=health;field=percent;operator=&lt;;value=30} true</span></span></code></pre></div><h2 id="mob-attributes" tabindex="-1">Mob attributes <a class="header-anchor" href="#mob-attributes" aria-label="Permalink to “Mob attributes”">​</a></h2><p>MythicMobs mobs can define an <code>EmakiAttribute</code> section:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">FireDragon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENDER_DRAGON</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  Health</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  EmakiAttribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;physical_attack: 100&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;physical_defense: 50&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spell_attack: 80&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;health: 500&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Every entry must be quoted</p><p><code>EmakiAttribute</code> is a string list. Written unquoted as <code>- physical_attack: 100</code>, YAML parses each entry as a mapping instead of a string, the whole section is skipped, the mob receives no attributes, and nothing is logged.</p><p>To check: run <code>/ea debug on</code> and enter combat, then look for your attribute IDs in the attacker snapshot. Seeing only <code>default_profile</code> entries means the section was not read.</p></div><p>Attributes are synchronized when Mythic mobs spawn, and active Mythic mobs are resynced after MythicMobs reloads.</p>`,38)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};